def transform(grid):
    # The large region of 1s is the picture; the isolated cells outside it
    # indicate the orientation in which that picture should be shown.
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    pic = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    h, w = len(pic), len(pic[0])

    outside = {}
    inside = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if not v:
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(v, []).append((r - r0, c - c0))
            else:
                outside.setdefault(v, []).append((r, c))

    colors = [v for v in outside if v in inside]
    if not colors:
        return pic

    def rotate(a):
        return [list(row) for row in zip(*a[::-1])]

    candidates = []
    a = pic
    for _ in range(4):
        candidates.append(a)
        candidates.append([row[::-1] for row in a])
        a = rotate(a)

    def centroid(points):
        return (sum(p[0] for p in points) / len(points),
                sum(p[1] for p in points) / len(points))

    def norm(point, hh, ww):
        r, c = point
        return (r / max(1, hh - 1), c / max(1, ww - 1))

    ext_points = {v: centroid(outside[v]) for v in colors}
    er = [p[0] for p in ext_points.values()]
    ec = [p[1] for p in ext_points.values()]
    eminr, emaxr, eminc, emaxc = min(er), max(er), min(ec), max(ec)
    ext_norm = {
        v: ((p[0] - eminr) / max(1, emaxr - eminr),
            (p[1] - eminc) / max(1, emaxc - eminc))
        for v, p in ext_points.items()
    }

    best, best_score = pic, float("inf")
    for cand in candidates:
        hh, ww = len(cand), len(cand[0])
        positions = {}
        for r, row in enumerate(cand):
            for c, value in enumerate(row):
                if value in colors:
                    positions.setdefault(value, []).append((r, c))
        score = 0.0
        for v in colors:
            p = norm(centroid(positions[v]), hh, ww)
            q = ext_norm[v]
            score += (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
        if score < best_score:
            best, best_score = cand, score
    return best
